    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
while True:
    k = rng.choice([3, 4])
    b = rng.choice([8, 9, 10, 12])
    d = rng.randint(2, b - 1)
    num_digits = rng.choice([3, 4])

    max_digit_sum = k * (d - 1)
    max_s = min(b - 1, max_digit_sum)

    # For the chosen k>=3 and d>=2, d < k/(k-1) is impossible, so max_s >= d is guaranteed.

    s_digits_msb_first = [rng.randint(0, max_s) for _ in range(num_digits)]

    # Condition 1: MSB is not zero
    if s_digits_msb_first[0] == 0:
        continue

    # Condition 2: At least one digit s_i >= d to make the problem non-trivial
    if not any(s >= d for s in s_digits_msb_first):
        continue

    # If we reach here, the digits are good. Convert to integer S.
    S = 0
    for digit in s_digits_msb_first:
        S = S * b + digit

    return {
        'k': k,
        'base': b,
        'capacity': d,
        'S': S
    }

